### Использование Accordion в Controlled варианте Использование Accordion в Controlled варианте ```tsx
    import React, { useState } from 'react';
    import { Accordion, AccordionItem, IconButton } from '@salutejs/sdds-finai';
    import { IconPlus } from '@salutejs/plasma-icons';

    export function App() {
        const [activeFirst, setActiveFirst] = useState(false);
        const [activeSecond, setActiveSecond] = useState(false);
        const [activeThree, setActiveThree] = useState(false);

        const contentRight = (active, setActive) => {
            return (
                <IconButton view="secondary" size="s" onClick={() => setActive(!active)}>
                    <IconPlus size="xs" />
                </IconButton>
            )
        }

        return (
            <div>
                <Accordion size="s" singleActive={true}>
                    <AccordionItem opened={activeFirst} contentRight={contentRight(activeFirst, setActiveFirst)} defaultIconContent="arrow" defaultIconPlacement="left" title="Как оплатить заправку бонусами СберСпасибо?">После указания деталей заправки нажмите кнопку «К оплате». Откроется окно оплаты, где вы сможете списать бонусы и оплатить ими до 99% стоимости топлива</AccordionItem>
                    <AccordionItem opened={activeSecond} contentRight={contentRight(activeSecond, setActiveSecond)} defaultIconContent="arrow" defaultIconPlacement="left" title="Как оплатить заправку бонусами СберСпасибо?">После указания деталей заправки нажмите кнопку «К оплате». Откроется окно оплаты, где вы сможете списать бонусы и оплатить ими до 99% стоимости топлива</AccordionItem>
                    <AccordionItem opened={activeThree} contentRight={contentRight(activeThree, setActiveThree)} defaultIconContent="arrow" defaultIconPlacement="left" title="Как оплатить заправку бонусами СберСпасибо?">После указания деталей заправки нажмите кнопку «К оплате». Откроется окно оплаты, где вы сможете списать бонусы и оплатить ими до 99% стоимости топлива</AccordionItem>
                </Accordion>
            </div>
        );
    }
```

